fn part(root: ToonNode, which: Text, name: Text) -> Int {
    ret toon_get_int_or(root, which + "." + name, 0);
}

fn version(root: ToonNode, which: Text) -> Text {
    ret int_to_text(part(root, which, "major")) + "." +
        int_to_text(part(root, which, "minor")) + "." +
        int_to_text(part(root, which, "patch"));
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"package\":\"fastq\",\"installed\":{\"major\":2,\"minor\":4,\"patch\":1},\"latest\":{\"major\":2,\"minor\":10,\"patch\":0}}");
    let root: ToonNode = toon_root(doc);
    let parts: Text[] = ["major", "minor", "patch"];
    let verdict: Text = "up to date";
    loop p in parts {
        let have: Int = part(root, "installed", p);
        let want: Int = part(root, "latest", p);
        if want > have {
            verdict = "update available (" + p + ")";
            break;
        }
        if want < have {
            break;
        }
    }
    fx {
        println(toon_get_text(root, "package"), " ", version(root, "installed"), " -> ", version(root, "latest"));
        println(verdict);
    }
    toon_close(doc);
    ret;
}

