type Entry {
    tag: Text;
    score: Int;
}

fn main() -> Void {
    let doc: ToonDoc = toon_parse("{\"game\":\"Asteroids\",\"players\":[{\"tag\":\"zed\",\"score\":4200},{\"tag\":\"amy\",\"score\":9100},{\"tag\":\"kai\",\"score\":6100},{\"tag\":\"lou\",\"score\":9100}]}");
    let root: ToonNode = toon_root(doc);
    let players: ToonNode = toon_key(root, "players");
    let board: Entry[] = [];
    loop p in players {
        board = board + [new Entry { tag: toon_get_text(p, "tag"), score: toon_get_int(p, "score") }];
    }
    loop i in 1..length(board) {
        let cur: Entry = board[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if board[j].score >= cur.score {
                break;
            }
            board[j + 1] = board[j];
            j = j - 1;
        }
        board[j + 1] = cur;
    }
    fx {
        println(toon_get_text(root, "game"), " leaderboard");
        loop k in 0..length(board) {
            println(k + 1, ". ", board[k].tag, " ", board[k].score);
        }
    }
    toon_close(doc);
    ret;
}

