fn pad3(n: Int) -> Text {
    if n < 10 {
        ret "00" + int_to_text(n);
    }
    if n < 100 {
        ret "0" + int_to_text(n);
    }
    ret int_to_text(n);
}

fn main() -> Void {
    let events: Text[] = ["boot", "load", "serve"];
    let out: MStream = mstream_new();
    loop i in 0..length(events) {
        appendText(out, pad3(i + 1));
        mstream_write_byte(out, ord(" "));
        appendText(out, events[i]);
        mstream_write_byte(out, 10);
    }
    let original: Text = mstream_text(out);
    let back: MStream = mstream_new();
    fx {
        mstream_save(out, "events.log");
        back = mstream_load("events.log");
        let ok: Bool = true;
        let loaded: Text = mstream_text(back);
        println("loaded=", ok);
        print(loaded);
        println("match=", loaded == original);
    }
    mstream_free(out);
    mstream_free(back);
    ret;
}

fn hexOf(text: Text) -> Text {
    let digits: Text = "0123456789ABCDEF";
    let ms: MStream = mstream_new();
    loop ch in text {
        let b: Int = ord(ch);
        mstream_write_byte(ms, ord(digits[b div 16]));
        mstream_write_byte(ms, ord(digits[b % 16]));
    }
    let encoded: Text = mstream_text(ms);
    mstream_free(ms);
    ret encoded;
}

