        println("in=", string_len(raw), " out=", string_len(quoted));
    }
    ret;
}

fn titleCase(s: Text) -> Text {
    let ms: MStream = mstream_new();
    let atWordStart: Bool = true;
    loop ch in s {
        let b: Int = ord(ch);
        if b == 32 {
            atWordStart = true;
            mstream_write_byte(ms, b);
        } else {
            if atWordStart && b >= 97 && b <= 122 {
                mstream_write_byte(ms, b - 32);
            } else {
                mstream_write_byte(ms, b);
            }
            atWordStart = false;
        }
    }
    let result: Text = mstream_text(ms);
    mstream_free(ms);
    ret result;
}

