fn toBinary(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let bits: Int[] = [];
    let v: Int = n;
    loop v > 0 {
        bits = bits + [v % 2];
        v = v div 2;
    }
    let ms: MStream = mstream_new();
    loop i in length(bits) - 1..-1 step -1 {
        mstream_write_byte(ms, 48 + bits[i]);
    }
    let out: Text = mstream_text(ms);
    mstream_free(ms);
    ret out;
}

