fn main() -> Void {
    let floor: Text[] = ["....#", ".#...", "...#.", "#....", "..#.."];
    let rows: Int = length(floor);
    let cols: Int = length(floor[0]);
    let ways: Int[][] = [];
    loop r in 0..rows {
        let line: Text = floor[r];
        let row: Int[] = [];
        loop c in 0..cols {
            let here: Int = 0;
            if line[c] == "#" {
                here = 0;
            } else if r == 0 && c == 0 {
                here = 1;
            } else {
                if r > 0 {
                    here = here + ways[r - 1][c];
                }
                if c > 0 {
                    here = here + row[c - 1];
                }
            }
            row = row + [here];
        }
        ways = ways + [row];
    }
    fx {
        loop r in 0..rows {
            loop c in 0..cols {
                print(ways[r][c]:4);
            }
            println("");
        }
        println("routes: ", ways[rows - 1][cols - 1]);
    }
    ret;
}

fn main() -> Void {
    let cost: Int[][] = [
        [3, 1, 4, 1, 5],
        [2, 7, 1, 8, 2],
        [6, 1, 3, 2, 9],
        [5, 4, 2, 6, 1]
    ];
    let rows: Int = length(cost);
    let cols: Int = length(cost[0]);
    let best: Int[][] = [];
    loop r in 0..rows {
        let row: Int[] = [];
        loop c in 0..cols {
            let v: Int = cost[r][c];
            if r == 0 && c == 0 {
                row = row + [v];
            } else if r == 0 {
                row = row + [row[c - 1] + v];
            } else if c == 0 {
                row = row + [best[r - 1][c] + v];
            } else {
                row = row + [min(best[r - 1][c], row[c - 1]) + v];
            }
        }
        best = best + [row];
    }

    let moves: Text = "";
    let y: Int = rows - 1;
    let x: Int = cols - 1;
    loop y > 0 || x > 0 {
        if y == 0 {
            moves = "R" + moves;
            x = x - 1;
        } else if x == 0 {
            moves = "D" + moves;
            y = y - 1;
        } else if best[y - 1][x] <= best[y][x - 1] {
            moves = "D" + moves;
            y = y - 1;
        } else {
            moves = "R" + moves;
            x = x - 1;
        }
    }
    fx {
        println("cheapest cost: ", best[rows - 1][cols - 1]);
        println("moves: ", moves);
    }
    ret;
}

