fn multiply(a: Int[][], b: Int[][]) -> Int[][] {
    let out: Int[][] = [];
    loop i in 0..length(a) {
        let row: Int[] = [];
        loop j in 0..length(b[0]) {
            let sum: Int = 0;
            loop k in 0..length(b) {
                sum = sum + a[i][k] * b[k][j];
            }
            row = row + [sum];
        }
        out = out + [row];
    }
    ret out;
}

