@pure
fn liveNeighbours(g: Bool[][], r: Int, c: Int) -> Int {
    let count: Int = 0;
    loop dr in -1..2 {
        loop dc in -1..2 {
            let y: Int = r + dr;
            let x: Int = c + dc;
            if (dr != 0 || dc != 0) && y >= 0 && y < length(g) && x >= 0 && x < length(g[y]) {
                if g[y][x] {
                    count = count + 1;
                }
            }
        }
    }
    ret count;
}

@pure
fn nextGeneration(g: Bool[][]) -> Bool[][] {
    let out: Bool[][] = [];
    loop r in 0..length(g) {
        let row: Bool[] = [];
        loop c in 0..length(g[r]) {
            let n: Int = liveNeighbours(g, r, c);
            if g[r][c] {
                row = row + [n == 2 || n == 3];
            } else {
                row = row + [n == 3];
            }
        }
        out = out + [row];
    }
    ret out;
}

