fn main() -> Void {
    let chart: Text[] = ["LL~~~L", "L~~LLL", "~~~~L~", "LL~~~~", "~L~LL~"];
    let rows: Int = length(chart);
    let cols: Int = length(chart[0]);
    let land: Bool[][] = [];
    let seen: Bool[][] = [];
    loop line in chart {
        let landRow: Bool[] = [];
        let seenRow: Bool[] = [];
        loop ch in line {
            landRow = landRow + [ch == "L"];
            seenRow = seenRow + [false];
        }
        land = land + [landRow];
        seen = seen + [seenRow];
    }
    let dr: Int[] = [-1, 1, 0, 0];
    let dc: Int[] = [0, 0, -1, 1];
    let sizes: Int[] = [];
    loop r in 0..rows {
        loop c in 0..cols {
            if land[r][c] && !seen[r][c] {
                let stack: Int[] = [r * cols + c];
                seen[r][c] = true;
                let size: Int = 0;
                loop length(stack) > 0 {
                    let cell: Int = stack[length(stack) - 1];
                    stack = stack[..length(stack) - 1];
                    size = size + 1;
                    let y: Int = cell div cols;
                    let x: Int = cell % cols;
                    loop d in 0..4 {
                        let ny: Int = y + dr[d];
                        let nx: Int = x + dc[d];
                        if ny >= 0 && ny < rows && nx >= 0 && nx < cols {
                            if land[ny][nx] && !seen[ny][nx] {
                                seen[ny][nx] = true;
                                stack = stack + [ny * cols + nx];
                            }
                        }
                    }
                }
                sizes = sizes + [size];
            }
        }
    }
    let largest: Int = 0;
    loop s in sizes {
        largest = max(largest, s);
    }
    fx {
        println("islands: ", length(sizes));
        print("sizes:");
        loop s in sizes {
            print(" ", s);
        }
        println("");
        println("largest: ", largest);
    }
    ret;
}

fn main() -> Void {
    let tri: Int[][] = [[5], [9, 6], [4, 6, 8], [0, 7, 1, 5], [8, 3, 1, 1, 2]];
    let best: Int[][] = [];
    loop r in 0..length(tri) {
        let row: Int[] = [];
        loop k in 0..length(tri[r]) {
            let v: Int = tri[r][k];
            if r == 0 {
                row = row + [v];
            } else if k == 0 {
                row = row + [v + best[r - 1][0]];
            } else if k == r {
                row = row + [v + best[r - 1][k - 1]];
            } else {
                row = row + [v + min(best[r - 1][k - 1], best[r - 1][k])];
            }
        }
        best = best + [row];
    }

    let last: Int = length(tri) - 1;
    let k: Int = 0;
    loop i in 1..length(best[last]) {
        if best[last][i] < best[last][k] {
            k = i;
        }
    }
    let total: Int = best[last][k];
    let path: Int[] = [tri[last][k]];
    loop r in last..0 step -1 {
        if k == r {
            k = k - 1;
        } else if k > 0 && best[r - 1][k - 1] <= best[r - 1][k] {
            k = k - 1;
        }
        path = [tri[r - 1][k]] + path;
    }
    fx {
        println("total: ", total);
        print("path: ", path[0]);
        loop i in 1..length(path) {
            print(" -> ", path[i]);
        }
        println("");
    }
    ret;
}

