    ret bits % 2 == 1;
}

@pure
fn nextRow(prev: Bool[], rule: Int) -> Bool[] {
    let width: Int = length(prev);
    let row: Bool[] = [];
    loop i in 0..width {
        let left: Int = if i > 0 && prev[i - 1] { 1 } else { 0 };
        let mid: Int = if prev[i] { 1 } else { 0 };
        let right: Int = if i < width - 1 && prev[i + 1] { 1 } else { 0 };
        row = row + [ruleBit(rule, left * 4 + mid * 2 + right)];
    }
    ret row;
}

