    loop r in 0..rows {
        let row: Int[] = [0; cols];
        best = best + [row];
    }
    loop c in cols - 1..-1 step -1 {
        loop r in 0..rows {
            let ahead: Int = 0;
            if c < cols - 1 {
                loop y in max(r - 1, 0)..min(r + 2, rows) {
                    ahead = max(ahead, best[y][c + 1]);
                }
            }
            best[r][c] = gold[r][c] + ahead;
