@pure
fn heaviestFirst(ws: Int[]) -> Int[] {
    let n: Int = length(ws);
    loop i in 0..n - 1 {
        let best: Int = i;
        loop j in i + 1..n {
            if ws[j] > ws[best] {
                best = j;
            }
        }
        if best != i {
            let tmp: Int = ws[i];
            ws[i] = ws[best];
            ws[best] = tmp;
        }
    }
    ret ws;
}

