@pure
fn gapPass(xs: Int[], gap: Int) -> Int[] {
    loop i in gap..length(xs) {
        let v: Int = xs[i];
        let j: Int = i;
        loop j >= gap && xs[j - gap] > v {
            xs[j] = xs[j - gap];
            j = j - gap;
        }
        xs[j] = v;
    }
    ret xs;
}

