type SortRun {
    items: Text[] = [];
    swaps: Int = 0;
}

@pure
fn gnomeSort(labels: Text[]) -> SortRun {
    let run: SortRun = new SortRun { items: labels };
    let i: Int = 1;
    loop i < length(run.items) {
        if i == 0 || run.items[i - 1] <= run.items[i] {
            i = i + 1;
        } else {
            let tmp: Text = run.items[i - 1];
            run.items[i - 1] = run.items[i];
            run.items[i] = tmp;
            run.swaps = run.swaps + 1;
            i = i - 1;
        }
    }
    ret run;
