fn pairsFor(prices: Int[], target: Int) -> Text {
    let lo: Int = 0;
    let hi: Int = length(prices) - 1;
    let found: Text = "";
    loop lo < hi {
        let sum: Int = prices[lo] + prices[hi];
        if sum == target {
            found = found + " " + int_to_text(prices[lo]) + "+" + int_to_text(prices[hi]);
            lo = lo + 1;
            hi = hi - 1;
        } else if sum < target {
            lo = lo + 1;
        } else {
            hi = hi - 1;
        }
    }
    if found == "" {
        ret " none";
    }
    ret found;
}

