type Ring {
    slots: Int[] = [];
    head: Int = 0;
    count: Int = 0;
    dropped: Int = 0;

    fn add(v: Int) -> Void {
        let cap: Int = length(self.slots);
        if self.count < cap {
            self.slots[(self.head + self.count) % cap] = v;
            self.count = self.count + 1;
        } else {
            self.slots[self.head] = v;
            self.head = (self.head + 1) % cap;
            self.dropped = self.dropped + 1;
        }
        ret;
    }

    fn inOrder() -> Int[] {
        let out: Int[] = [];
        loop k in 0..self.count {
            out = out + [self.slots[(self.head + k) % length(self.slots)]];
        }
        ret out;
    }
}

fn main() -> Void {
    let ring: Ring = new Ring();
    ring.slots = [0; 4];
    let feed: Int[] = [18, 21, 19, 23, 25, 22, 20];
    loop t in feed {
        ring.add(t);
    }
    let latest: Int[] = ring.inOrder();
    let sum: Int = 0;
    loop t in latest {
        sum = sum + t;
    }
    fx {
        print("latest:");
        loop t in latest {
            print(" ", t);
        }
        println("");
        println("overwritten=", ring.dropped);
        println("avg=", sum * 1.0 / length(latest):0:2);
    }
    ret;
}

