fn factorText(n: Int) -> Text {
    let rest: Int = n;
    let out: Text = "";
    let p: Int = 2;
    loop p * p <= rest {
        let count: Int = 0;
        loop rest % p == 0 {
            rest = rest div p;
            count = count + 1;
        }
        if count > 0 {
            if out != "" {
                out = out + " x ";
            }
            out = out + int_to_text(p);
            if count > 1 {
                out = out + "^" + int_to_text(count);
            }
        }
        if p == 2 {
            p = 3;
        } else {
            p = p + 2;
        }
    }
    if rest > 1 {
        if out != "" {
            out = out + " x ";
        }
        out = out + int_to_text(rest);
    }
    ret out;
}

