            let kind: Text = "";
            if s == n {
                kind = "perfect";
            } else if s > n {
                kind = "abundant";
            } else {
                kind = "deficient";
            }
            println(n, " ", kind, " (divisor sum ", s, ")");
        }
    }
    ret;
}

