fn isArmstrong(n: Int, k: Int) -> Bool {
    let rest: Int = n;
    let total: Int = 0;
    loop rest > 0 {
        let digit: Int = rest % 10;
        let term: Int = 1;
        loop j in 0..k {
            term = term * digit;
        }
        total = total + term;
        rest = rest div 10;
    }
    ret total == n;
}

