}

fn floorRoot(n: Int) -> Int {
    let r: Int = 0;
    loop (r + 1) * (r + 1) <= n {
        r = r + 1;
    }
    ret r;
}

fn main() -> Void {
    let numbers: Int[] = [1, 10, 15, 36, 50, 100, 120, 1225, 2016];
    fx {
        loop n in numbers {
            let r: Int = floorRoot(n);
            let isSquare: Bool = r * r == n;
            let t: Int = floorRoot(8 * n + 1);
            let isTriangular: Bool = t * t == 8 * n + 1;
            let k: Int = (t - 1) div 2;
            if isTriangular && isSquare {
                println(n, ": both T", k, " ", r, "^2");
            } else if isTriangular {
                println(n, ": triangular T", k);
            } else if isSquare {
                println(n, ": square ", r, "^2");
            } else {
                println(n, ": neither");
            }
        }
    }
    ret;
}

fn gcd(a: Int, b: Int) -> Int {
    let x: Int = a;
    let y: Int = b;
    loop y != 0 {
        let r: Int = x % y;
        x = y;
        y = r;
    }
    ret x;
}

fn lcmOf(xs: Int[]) -> Int {
    let result: Int = 1;
    loop x in xs {
        result = result div gcd(result, x) * x;
    }
    ret result;
}

