fn checkIsbn(code: Text) -> Text {
    let digits: Int[] = [];
    let last: Int = string_len(code) - 1;
    loop i in 0..string_len(code) {
        let ch: Text = code[i];
        if ord(ch) >= ord("0") && ord(ch) <= ord("9") {
            digits = digits + [ord(ch) - ord("0")];
        } else if ch == "X" && i == last {
            digits = digits + [10];
        } else if ch == "-" {
            continue;
        } else {
            ret "invalid (character)";
        }
    }
    if length(digits) != 10 {
        ret "invalid (length)";
    }
    let sum: Int = 0;
    loop weight in 10..0 step -1 {
        sum = sum + weight * digits[10 - weight];
    }
    if sum % 11 == 0 {
        ret "valid";
    }
    ret "invalid (checksum)";
}

fn checkDigit(prefix: Text) -> Text {
    let sum: Int = 0;
    loop i in 0..9 {
        sum = sum + (10 - i) * (ord(prefix[i]) - ord("0"));
    }
    let d: Int = (11 - sum % 11) % 11;
    if d == 10 {
        ret "X";
    }
    ret int_to_text(d);
}

