        }
    }
    ret;
}

fn shiftText(message: Text, shift: Int) -> Text {
    let out: Text = "";
    loop ch in message {
        let code: Int = ord(ch);
        let base: Int = -1;
        if code >= ord("A") && code <= ord("Z") {
            base = ord("A");
        } else if code >= ord("a") && code <= ord("z") {
            base = ord("a");
        }
        if base < 0 {
            out = out + ch;
        } else {
            let offset: Int = ((code - base + shift) % 26 + 26) % 26;
            out = out + chr(base + offset);
        }
    }
    ret out;
}

