}

fn diagonalSum(size: Int) -> Int {
    let total: Int = 1;
    loop side in 3..size + 1 step 2 {
        let corner: Int = side * side;
        let gap: Int = side - 1;
        total = total + 4 * corner - 6 * gap;
    }
    ret total;
}

