fn columnName(n: Int) -> Text {
    let rest: Int = n;
    let out: Text = "";
    loop rest > 0 {
        rest = rest - 1;
        out = chr(ord("A") + rest % 26) + out;
        rest = rest div 26;
    }
    ret out;
}

