        println("Kiln ", toon_get_text_or(root, "kiln", "?"));
        loop f in firings {
            let cone: Int = toon_get_int_or(f, "cone", 0);
            let kind: Text = "bisque";
            if toon_get_bool_or(f, "glazed", false) {
                kind = "glazed";
                glazed = glazed + 1;
            }
            hottest = max(hottest, cone);
            println(toon_get_text_or(f, "piece", "?"), " cone ", cone, " ", kind);
        }
        println("glazed: ", glazed, " of ", toon_len(firings));
        println("hottest cone: ", hottest);
        toon_close(doc);
    }
    ret;
}

