@pure
fn shortfall(stock: Int, minimum: Int) -> Int {
    if stock < minimum {
        ret minimum - stock;
    }
    ret 0;
}

fn main() -> Void {
    let doc: ToonDoc;
    fx {
        doc = toon_parse_file("bins.json");
    }
    let root: ToonNode = toon_root(doc);
    let bins: ToonNode = toon_key(root, "bins");
    let name: Text = toon_get_text_or(root, "warehouse", "?");
    let total: Int = toon_len(bins);
    let codes: Text[] = [];
    let needs: Int[] = [];
    loop i in 0..total {
        let b: ToonNode = toon_at(bins, i);
        let need: Int = shortfall(toon_get_int_or(b, "stock", 0), toon_get_int_or(b, "min", 0));
        if need > 0 {
            codes = codes + [toon_get_text_or(b, "code", "?")];
            needs = needs + [need];
        }
    }
    toon_close(doc);
    fx {
        println(name, " reorder list");
        loop i in 0..length(codes) {
            println(codes[i], " needs ", needs[i]);
        }
        println("bins to reorder: ", length(codes), " of ", total);
    }
    ret;
}

