@pure
fn scaledLines(raw: Text, people: Int) -> Text[] {
    let doc: ToonDoc = toon_parse(raw);
    let root: ToonNode = toon_root(doc);
    let serves: Int = toon_get_int_or(root, "serves", 1);
    let out: Text[] = [toon_get_text_or(root, "recipe", "?") + " for " + int_to_text(people)];
    loop ing in toon_key(root, "ingredients") {
        let grams: Int = toon_get_int_or(ing, "grams", 0) * people div serves;
        out = out + [toon_get_text_or(ing, "name", "?") + " " + int_to_text(grams) + " g"];
    }
    toon_close(doc);
    ret out;
}

