@pure
fn twoDigits(n: Int) -> Text {
    if n < 10 {
        ret "0" + int_to_text(n);
    }
    ret int_to_text(n);
}

@pure
fn clockText(secs: Int) -> Text {
    ret int_to_text(secs div 3600) + ":" + twoDigits(secs % 3600 div 60) + ":" + twoDigits(secs % 60);
}

