        let warm: Int = 0;
        loop line in lines {
            if isWarm(line) {
                warm = warm + 1;
                warmIds = warmIds + [split(line, " ")[0]];
            }
        }
        report = report + [name + ": " + int_to_text(length(lines)) + " samples, " + int_to_text(warm) + " warm"];
