@pure
fn digitsOf(n: Int) -> Int[] {
    let rev: Int[] = [];
    let rest: Int = n;
    loop rest > 0 {
        rev = rev + [rest % 10];
        rest = rest div 10;
    }
    ret reversed(rev);
}

