fn siftDown(heap: Int[], start: Int, size: Int) -> Int[] {
    let root: Int = start;
    loop 2 * root + 1 < size {
        let child: Int = 2 * root + 1;
        if child + 1 < size && heap[child + 1] > heap[child] {
            child = child + 1;
        }
        if heap[root] >= heap[child] {
            break;
        }
        let tmp: Int = heap[root];
        heap[root] = heap[child];
        heap[child] = tmp;
        root = child;
    }
    ret heap;
}

fn heapSorted(temps: Int[]) -> Int[] {
    let heap: Int[] = temps;
    let n: Int = length(heap);
    let i: Int = n div 2 - 1;
    loop i >= 0 {
        heap = siftDown(heap, i, n);
        i = i - 1;
    }
    let last: Int = n - 1;
    loop last > 0 {
        let top: Int = heap[0];
        heap[0] = heap[last];
        heap[last] = top;
        heap = siftDown(heap, 0, last);
        last = last - 1;
    }
    ret heap;
}

