fn heaviestHives(weights: Int[], k: Int) -> Int[] {
    let heap: Int[] = weights;
    let size: Int = length(heap);
    fn sink(start: Int, limit: Int) -> Void {
        let at: Int = start;
        loop 2 * at + 1 < limit {
            let child: Int = 2 * at + 1;
            if child + 1 < limit && heap[child + 1] > heap[child] {
                child = child + 1;
            }
            if heap[at] >= heap[child] {
                ret;
            }
            let tmp: Int = heap[at];
            heap[at] = heap[child];
            heap[child] = tmp;
            at = child;
        }
        ret;
    }
    loop i in 0..size div 2 {
        sink(size div 2 - 1 - i, size);
    }
    let out: Int[] = [];
    loop length(out) < k && size > 0 {
        out = out + [heap[0]];
        size = size - 1;
        heap[0] = heap[size];
        sink(0, size);
    }
    ret out;
}

fn main() -> Void {
    let weights: Int[] = [31, 44, 27, 52, 38, 49, 29, 41, 36];
    let top3: Int[] = heaviestHives(weights, 3);
    let top5: Int[] = heaviestHives(weights, 5);
    fx {
