}

fn quickSorted(times: Int[]) -> Int[] {
    let xs: Int[] = times;
    fn partition(lo: Int, hi: Int) -> Int {
        let pivot: Int = xs[hi];
        let store: Int = lo;
        loop j in lo..hi {
            if xs[j] < pivot {
                let tmp: Int = xs[store];
                xs[store] = xs[j];
                xs[j] = tmp;
                store = store + 1;
            }
        }
        let last: Int = xs[store];
        xs[store] = xs[hi];
        xs[hi] = last;
        ret store;
    }
    fn sortRange(lo: Int, hi: Int) -> Void {
        if lo >= hi {
            ret;
        }
        let p: Int = partition(lo, hi);
        sortRange(lo, p - 1);
        sortRange(p + 1, hi);
        ret;
    }
    sortRange(0, length(xs) - 1);
    ret xs;
}

fn main() -> Void {
    let times: Int[] = [241, 198, 305, 226, 187, 263, 219, 198, 284, 175];
    let ordered: Int[] = quickSorted(times);
    let median: Real = (ordered[4] + ordered[5]) / 2.0;
    let fast: Int = 0;
