fn rotateLeft(seats: Int[], k: Int) -> Int[] {
    let n: Int = length(seats);
    let shift: Int = k % n;
    let out: Int[] = reverseSpan(seats, 0, shift - 1);
    out = reverseSpan(out, shift, n - 1);
    out = reverseSpan(out, 0, n - 1);
    ret out;
}

