type LineUp {
    heights: Int[] = [];
    swaps: Int = 0;
    passes: Int = 0;
}

fn lineUp(heights: Int[]) -> LineUp {
    let result: LineUp = new LineUp { heights: heights };
    let n: Int = length(heights);
    let swapped: Bool = true;
    loop swapped {
        swapped = false;
        result.passes = result.passes + 1;
        loop j in 0..n - 1 {
            if result.heights[j] > result.heights[j + 1] {
                let tmp: Int = result.heights[j];
                result.heights[j] = result.heights[j + 1];
                result.heights[j + 1] = tmp;
                result.swaps = result.swaps + 1;
                swapped = true;
            }
        }
        n = n - 1;
    }
    ret result;
}

