fn heapPush(heap: Int[], v: Int) -> Int[] {
    let h: Int[] = heap + [v];
    let i: Int = length(h) - 1;
    loop i > 0 {
        let parent: Int = (i - 1) div 2;
        if h[parent] <= h[i] {
            break;
        }
        let tmp: Int = h[parent];
        h[parent] = h[i];
        h[i] = tmp;
        i = parent;
    }
    ret h;
}

fn heapPop(heap: Int[]) -> (Int, Int[]) {
    let top: Int = heap[0];
    let n: Int = length(heap) - 1;
    let h: Int[] = heap[..n];
    if n == 0 {
        ret (top, h);
    }
    h[0] = heap[n];
    let i: Int = 0;
    loop 2 * i + 1 < n {
        let child: Int = 2 * i + 1;
        if child + 1 < n && h[child + 1] < h[child] {
            child = child + 1;
        }
        if h[i] <= h[child] {
            break;
        }
        let tmp: Int = h[i];
        h[i] = h[child];
        h[child] = tmp;
        i = child;
    }
    ret (top, h);
}

fn main() -> Void {
    let ops: Int[] = [5, 2, 8, -1, 1, 7, -1, -1, 3, -1, -1, -1];
    let heap: Int[] = [];
    loop op in ops {
        if op >= 0 {
            heap = heapPush(heap, op);
            fx {
                println("push ", op, " (size ", length(heap), ")");
            }
        } else {
            let (v, rest) = heapPop(heap);
            heap = rest;
            fx {
                println("serve ", v, " (size ", length(heap), ")");
            }
        }
    }
    ret;
}

