    grid = markCell(grid, 0, 0);
    let reached: Int = 1;
    loop length(stack) > 0 {
        let cell: Int = stack[length(stack) - 1];
        stack = stack[..length(stack) - 1];
        let r: Int = cell div cols;
        let c: Int = cell % cols;
        loop d in 0..4 {
            let nr: Int = r + dr[d];
            let nc: Int = c + dc[d];
            if nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == 0 {
                grid = markCell(grid, nr, nc);
                reached = reached + 1;
                stack = stack + [nr * cols + nc];
            }
        }
    }
    fx {
        loop row in grid {
            let parts: Text[] = [];
            loop v in row {
                parts = parts + [int_to_text(v)];
            }
            println(join(parts, " "));
        }
        println("reached: ", reached);
    }
    ret;
}

@pure
fn isOrderCode(code: Text) -> Bool {
    if string_len(code) != 7 {
        ret false;
    }
    ret is_upper(code[..3]) && is_digit(code[3..]);
}

fn main() -> Void {
    let codes: Text[] = ["QRT0042", "qrt0042", "QR10042", "QRT004", "ZZZ9999", "AB C123"];
    fx {
        loop code in codes {
            if isOrderCode(code) {
                println(code, " ok");
            } else {
                println(code, " bad");
            }
        }
    }
    ret;
}

@pure
fn numbersIn(s: Text) -> Int[] {
    let out: Int[] = [];
    let run: Text = "";
    loop ch in s {
        if is_digit(ch) {
            run = run + ch;
        } else if string_len(run) > 0 {
            out = out + [parse_int(run)];
            run = "";
        }
    }
    if string_len(run) > 0 {
        out = out + [parse_int(run)];
    }
    ret out;
}

fn main() -> Void {
    let line: Text = "Order 12 has 3 items at 450 cents, ref 7";
    let nums: Int[] = numbersIn(line);
    let parts: Text[] = [];
    loop n in nums {
        parts = parts + [int_to_text(n)];
    }
    fx {
        println("numbers: ", join(parts, " "));
        println("sum: ", sum(nums));
    }
    ret;
}

@pure
fn problems(pw: Text) -> Text[] {
    let upperSeen: Bool = false;
    let lowerSeen: Bool = false;
    let digitSeen: Bool = false;
    let spaceSeen: Bool = false;
    loop ch in pw {
        if is_upper(ch) { upperSeen = true; }
        if is_lower(ch) { lowerSeen = true; }
        if is_digit(ch) { digitSeen = true; }
        if is_space(ch) { spaceSeen = true; }
    }
    let out: Text[] = [];
    if string_len(pw) < 8 { out = out + ["too short"]; }
    if !upperSeen { out = out + ["no upper-case letter"]; }
    if !lowerSeen { out = out + ["no lower-case letter"]; }
    if !digitSeen { out = out + ["no digit"]; }
    if spaceSeen { out = out + ["contains whitespace"]; }
    ret out;
}

fn main() -> Void {
    let candidates: Text[] = ["Harbor42Light", "short1A", "alllowercase9", "NO DIGITS here", "Tr1ckyPass"];
    fx {
        loop pw in candidates {
            let found: Text[] = problems(pw);
            if length(found) == 0 {
                println(pw, ": accepted");
            } else {
                println(pw, ": ", join(found, ", "));
            }
        }
    }
    ret;
}

@pure
fn collapse(s: Text) -> Text {
    let out: Text = "";
    let pending: Bool = false;
    loop ch in s {
        if is_space(ch) {
            pending = string_len(out) > 0;
        } else {
            if pending {
                out = out + " ";
                pending = false;
            }
            out = out + ch;
        }
    }
    ret out;
}

fn main() -> Void {
    let raw: Text[] = ["  the   quick\tbrown \n fox  ", "single", "\t\t", "a  b\n\nc"];
    fx {
        loop s in raw {
            println("[", collapse(s), "]");
        }
    }
    ret;
}

@pure
fn isIdentifier(name: Text) -> Bool {
    if string_len(name) == 0 {
        ret false;
    }
    if !is_alpha(name[0]) && name[0] != "_" {
        ret false;
    }
    loop i in 1..string_len(name) {
        let ch: Text = name[i];
        if !is_alnum(ch) && ch != "_" {
            ret false;
        }
    }
    ret true;
}

fn main() -> Void {
    let names: Text[] = ["total", "_tmp1", "9lives", "max-value", "", "camelCase2", "x"];
    fx {
        loop name in names {
            println("'", name, "' -> ", isIdentifier(name));
        }
    }
    ret;
}

