@pure
fn swapCase(s: Text) -> Text {
    let out: Text = "";
    loop ch in s {
        if is_upper(ch) {
            out = out + lower(ch);
        } else if is_lower(ch) {
            out = out + upper(ch);
        } else {
            out = out + ch;
        }
    }
    ret out;
}

fn main() -> Void {
    let words: Text[] = ["Aether 2026 Rocks", "hELLO", "MiXeD-case_42"];
    fx {
        loop w in words {
            println(w, " => ", swapCase(w));
        }
    }
    ret;
}

